"""nl — prophets_c."""

T = {
"prophets_151": ("Wat mochten Adam en zijn vrouw in de Tuin niet naderen?", ["Een boom", "Een rivier", "Een poort", "Een berg"], "Allah stond hun toe vrij te eten, behalve één enkele boom te naderen."),
"prophets_152": ("Wat ontving Adam volgens de Koran van zijn Heer na zijn misstap?", ["Woorden (van berouw), en Allah aanvaardde zijn berouw", "Rijkdom", "Een koninkrijk", "Een boek"], "«Toen ontving Adam woorden van zijn Heer, en Hij aanvaardde zijn berouw.»"),
"prophets_153": ("Met wie vergelijkt de Koran 'Isa, wat zijn schepping betreft?", ["Adam, geschapen uit stof", "Nuh (Noach)", "Ibrahim (Abraham)", "Yahya (Johannes)"], "«Voorwaar, het geval van 'Isa is bij Allah als het geval van Adam: Hij schiep hem uit stof en zei toen tot hem: “Wees!” en hij was.»"),
"prophets_154": ("Over welke profeet zegt de Koran dat hij waarachtig was en dat Allah hem tot een hoge plaats verhief?", ["Idris (Henoch)", "Ilyas (Elia)", "Dhul-Kifl", "Al-Yasa' (Elisa)"], "«En vermeld Idris in het Boek: hij was waarachtig, een profeet; en Wij verhieven hem tot een hoge plaats.»"),
"prophets_155": ("Wat zei Nuh toen zijn volk aan boord van de ark ging?", ["«In de naam van Allah zij haar vaart en haar ankerplaats»", "«Vrees de zee niet»", "«Neem jullie proviand mee»", "«Wacht tot het donker wordt»"], "«Ga aan boord: in de naam van Allah zij haar vaart en haar ankerplaats.»"),
"prophets_156": ("Wat vroeg de profeet Nuh in soera Nuh aan zijn Heer over de ongelovigen?", ["Dat er van hen niemand op aarde zou achterblijven", "Dat zij rijk zouden worden", "Dat zij nog een jaar zouden krijgen", "Dat zij verbannen zouden worden"], "«Mijn Heer, laat op aarde van de ongelovigen geen enkele bewoner achter.»"),
"prophets_157": ("Hoeveel van elke soort moest Nuh aan boord van de ark nemen?", ["Een paar", "Drie", "Tien", "Slechts één"], "Allah beval hem van elke soort een paar aan boord te laden, samen met zijn familie."),
"prophets_158": ("Hud herinnerde 'Ad eraan dat Allah hen opvolgers had gemaakt na welk volk?", ["Het volk van Nuh (Noach)", "Het volk van Lut (Lot)", "Het volk van Musa (Mozes)", "Het volk van Saba"], "«Gedenk toen Hij jullie opvolgers maakte na het volk van Nuh en jullie in gestalte ruim vermeerderde.»"),
"prophets_159": ("Waardoor werd het volk van 'Ad vernietigd, volgens soera Al-Haqqah?", ["Een razende, ijzige wind", "Een vloed", "Een aardbeving", "Een sprinkhanenzwerm"], "«Wat 'Ad betreft, zij werden vernietigd door een gierende, geweldige wind.»"),
"prophets_160": ("Wat verweet Hud zijn volk, dat op elke hoogte bouwde?", ["Uit ijdelheid bouwen en hopen eeuwig te leven", "Het land bewerken", "Ver weg handel drijven", "'s Nachts reizen"], "«Bouwen jullie op elke hoogte een teken, om jullie te vermaken, en nemen jullie paleizen alsof jullie eeuwig zouden leven?»"),
"prophets_161": ("Wat deed Thamud met de bergen, volgens de Koran?", ["Zij hieuwen er huizen uit", "Zij verborgen er goud in", "Zij weidden er hun kudden", "Zij vermeden ze"], "«Jullie nemen paleizen uit haar vlakten en houwen huizen uit de bergen.»"),
"prophets_162": ("Volgens soera Al-Qamar werd de kameelmerrie naar Thamud gezonden als wat?", ["Een beproeving voor hen", "Een beloning", "Een geschenk van hun koning", "Een kudde om te verkopen"], "«Wij zenden de kameelmerrie als een beproeving voor hen; sla hen dus gade en wees geduldig.»"),
"prophets_163": ("Wat greep Thamud nadat zij de kameelmerrie hadden gedood?", ["De aardbeving (ar-rajfah)", "De vloed", "De ijzige wind", "De hongersnood"], "«Toen greep de aardbeving hen, en zij lagen neergeveld in hun huizen.»"),
"prophets_164": ("Welke profeet werd gezonden naar het volk dat de grote schandelijkheid beging, zeggend: «Vrezen jullie Allah niet?»", ["Lut (Lot)", "Salih", "Hud", "Shu'ayb"], "«Toen hun broeder Lut tot hen zei: “Vrezen jullie Allah niet?”»"),
"prophets_165": ("Wat werd Lut bevolen te doen op de nacht van de bestraffing?", ["Bij nacht met zijn familie vertrekken en niet omkijken", "Zijn volk verzamelen", "De dageraad afwachten", "Zich in de berg verschuilen"], "«Vertrek dus met je familie in een deel van de nacht, en laat niemand van jullie omkijken.»"),
"prophets_166": ("Welke profeet werd gezonden naar het volk van Madyan, dat bedroog in maat en gewicht?", ["Shu'ayb", "Lut (Lot)", "Hud", "Ilyas (Elia)"], "Shu'ayb beval hun volle maat en eerlijk gewicht te geven, en geen verderf op aarde te zaaien."),
"prophets_167": ("Wat zei Shu'ayb tegen zijn volk dat hij werkelijk wilde?", ["«Ik wil slechts verbetering, zoveel als ik kan»", "«Ik wil slechts rijkdom»", "«Ik wil heersen»", "«Ik wil vertrekken»"], "«Ik wil slechts verbetering, zoveel als ik kan. En mijn welslagen is slechts door Allah.»"),
"prophets_168": ("Nadat Allah Ibrahim had beproefd met geboden die hij vervulde, wat zei Hij tot hem?", ["«Ik maak jou tot een leider (imam) voor de mensen»", "«Ik geef jou een koninkrijk»", "«Ik maak jou rijk»", "«Ik maak jou koning van Babylon»"], "«Ik maak jou tot een leider voor de mensen.» Ibrahim vroeg: «En van mijn nakomelingen?»"),
"prophets_169": ("Hoe legde Ibrahim de koning het zwijgen op die beweerde leven en dood te geven?", ["«Allah brengt de zon uit het oosten; breng jij haar uit het westen»", "«Laat de regen vallen»", "«Verplaats deze berg»", "«Tel de sterren»"], "«Allah brengt de zon uit het oosten, breng jij haar dan uit het westen.» De ongelovige stond verbijsterd."),
"prophets_170": ("Wat werd Ibrahim bevolen aan de mensen te verkondigen over het Heilige Huis?", ["De bedevaart: zij zullen te voet komen en op elke magere kameel", "De handel", "De oorlog", "Het zwijgen"], "«En verkondig onder de mensen de hadj: zij zullen tot jou komen te voet en op elke magere kameel.»"),
"prophets_171": ("Wat zette Ibrahim zijn geëerde gasten voor, dat zij niet aanraakten?", ["Een geroosterd gemest kalf", "Brood en water", "Dadels", "Melk"], "Hij ging naar zijn huisgenoten en bracht een vet kalf; toen hij zag dat hun handen er niet naar reikten, voelde hij vrees."),
"prophets_172": ("Over wie zegt de Koran dat hij «een uitstekend voorbeeld» (uswa hasana) is voor de gelovigen, samen met wie bij hem waren?", ["Ibrahim (Abraham)", "Nuh (Noach)", "Musa (Mozes)", "Dawud (David)"], "«Er is voor jullie een uitstekend voorbeeld geweest in Ibrahim en hen die bij hem waren.»"),
"prophets_173": ("Wat vroeg Ibrahim in soera Ibrahim voor de stad Mekka?", ["Dat zij veilig zou zijn, en dat hij en zijn zonen van afgodendienst gevrijwaard zouden blijven", "Dat zij een grote markt zou worden", "Dat zij paleizen zou hebben", "Dat zij leeg zou blijven"], "«Mijn Heer, maak deze stad veilig, en houd mij en mijn zonen ver van het aanbidden van afgoden.»"),
"prophets_174": ("Wat zei Ibrahim toen hij zijn volk verliet?", ["«Ik ga naar mijn Heer; Hij zal mij leiden»", "«Ik ga fortuin zoeken»", "«Ik keer terug om hen te bestrijden»", "«Ik ga naar Egypte»"], "«Voorwaar, ik ga naar mijn Heer; Hij zal mij leiden.»"),
"prophets_175": ("Over welke profeet zegt de Koran dat hij «zijn belofte nakwam» en zijn familie het gebed en de zakat opdroeg?", ["Isma'il (Ismaël)", "Ishaq (Isaak)", "Ya'qub (Jakob)", "Yusuf (Jozef)"], "«Hij kwam zijn belofte na, en hij was een gezant en een profeet. Hij droeg zijn familie het gebed en de zakat op.»"),
"prophets_176": ("Wat raadde Ya'qub Yusuf aan na zijn droom?", ["Hem niet aan zijn broers te vertellen", "Het aan iedereen te vertellen", "Hem op te schrijven", "Hem te vergeten"], "«Mijn zoon, vertel je droom niet aan je broers, anders beramen zij een list tegen jou.»"),
"prophets_177": ("Welk teken bewees Yusufs onschuld voor de heer des huizes?", ["Zijn hemd was aan de achterkant gescheurd", "Een verborgen getuige", "Een brief", "Een eed"], "Als het hemd van achteren gescheurd was, dan loog zij en behoort hij tot de waarachtigen."),
"prophets_178": ("Wat deden de vrouwen van de stad toen zij Yusuf zagen?", ["Zij sneden zich van verbazing in de handen", "Zij vluchtten", "Zij zwegen", "Zij lachten"], "«Toen zij hem zagen, prezen zij hem en sneden zich in de handen, zeggend: “Dit is geen mens; dit is niet anders dan een edele engel.”»"),
"prophets_179": ("Wat onderwees Yusuf zijn twee medegevangenen voordat hij hun dromen uitlegde?", ["De eenheid van Allah, en dat het oordeel Hem alleen toekomt", "De geneeskunde", "Het berekenen van oogsten", "De dichtkunst"], "«Zijn verschillende heren beter, of Allah, de Ene, de Overheersende? … Het oordeel komt alleen Allah toe.»"),
"prophets_180": ("Wat zei de koning van Egypte tot Yusuf nadat hij met hem had gesproken?", ["«Vandaag ben je bij ons een man van aanzien en vertrouwen»", "«Keer terug naar de gevangenis»", "«Verlaat Egypte»", "«Ik geef je mijn dochter»"], "«En toen hij met hem had gesproken, zei hij: “Voorwaar, je bent vandaag bij ons een man van aanzien en vertrouwen.”»"),
"prophets_181": ("Hoe hield Yusuf zijn broer bij zich?", ["De beker van de koning werd in de zak van zijn broer gevonden", "Hij kocht hem", "Hij zette hem zonder reden gevangen", "Hij maakte hem minister"], "«Zo beraamden Wij het voor Yusuf»: de beker kwam uit de zak van zijn broer tevoorschijn."),
"prophets_182": ("Wat zei Yusuf tot zijn broers toen zij hun fout toegaven?", ["«Vandaag treft jullie geen verwijt»", "«Jullie zullen gestraft worden»", "«Ga en kom nooit terug»", "«Ik ben jullie vergeten»"], "«Vandaag treft jullie geen verwijt. Moge Allah jullie vergeven; Hij is de Barmhartigste der barmhartigen.»"),
"prophets_183": ("Wat zei Ya'qub tot zijn zonen over wanhoop?", ["«Wanhoop niet aan de barmhartigheid van Allah»", "«Reis nooit meer»", "«Spreek met niemand»", "«Schrijf niets op»"], "«Wanhoop niet aan de verlichting van Allah: niemand wanhoopt aan de verlichting van Allah behalve het ongelovige volk.»"),
"prophets_184": ("Welke smeekbede deed Yusuf aan het einde van zijn verhaal?", ["Als overgegevene te sterven en bij de rechtschapenen gevoegd te worden", "Heel Egypte te regeren", "Naar Kanaän terug te keren", "Lang te leven"], "«Laat mij als moslim sterven en voeg mij bij de rechtschapenen.»"),
"prophets_185": ("Hoe richtte Ayyub zich tot zijn Heer in zijn beproeving?", ["«Tegenspoed heeft mij getroffen, en U bent de Barmhartigste»", "«Waarom ik?»", "«Geef mij mijn rijkdom terug»", "«Vernietig mijn vijanden»"], "«En gedenk Onze dienaar Ayyub, toen hij zijn Heer aanriep: “De satan heeft mij met vermoeidheid en kwelling getroffen.”»"),
"prophets_186": ("Wat gaf Allah Ayyub terug na de beproeving, volgens soera Sad?", ["Zijn familie, en nog eens zoveel met hen", "Een koninkrijk", "Een schip", "Een kudde kamelen"], "«En Wij schonken hem zijn familie en nog eens zoveel met hen, als barmhartigheid van Ons en als vermaning voor de bezitters van verstand.»"),
"prophets_187": ("Wat redde Yunus volgens soera As-Saffat ervan in de buik van de vis te blijven?", ["Dat hij tot hen behoorde die Allah verheerlijken", "Zijn kracht", "Een voorbijvarend schip", "Een gunstige wind"], "«En als hij niet tot hen had behoord die Allah verheerlijken, dan was hij in haar buik gebleven tot de Dag waarop zij worden opgewekt.»"),
"prophets_188": ("Welk volk geloofde volgens de Koran vóór de bestraffing hen bereikte, zodat het hun baatte?", ["Het volk van Yunus (Jona)", "Het volk van Nuh", "Het volk van Lut", "Het volk van Hud"], "«Was er dan geen stad die geloofde en wier geloof haar baatte, behalve het volk van Yunus?»"),
"prophets_189": ("Hoe noemt de Koran Yunus wanneer de Profeet ﷺ wordt gezegd niet als hem te zijn in ongeduld?", ["«De metgezel van de vis» (sahib al-hut)", "«De man met de staf»", "«De man van de berg»", "«De man van de put»"], "«En wees niet als de metgezel van de vis, toen hij riep terwijl hij vol verdriet was.»"),
"prophets_190": ("Welke profeet berispte zijn volk omdat het Ba'l aanriep en de beste der scheppers verliet?", ["Ilyas (Elia)", "Al-Yasa' (Elisa)", "Yunus (Jona)", "Shu'ayb"], "«En voorwaar, Ilyas behoorde tot de gezanten… “Roepen jullie Ba'l aan en verlaten jullie de beste der scheppers?”»"),
"prophets_191": ("Welke profeet noemt de Koran naast Isma'il en Idris onder de geduldigen die Allah in Zijn barmhartigheid opnam?", ["Dhul-Kifl", "Ilyas (Elia)", "Yunus (Jona)", "Al-Yasa' (Elisa)"], "«En Isma'il, Idris en Dhul-Kifl — allen behoorden tot de geduldigen. En Wij namen hen op in Onze barmhartigheid.»"),
"prophets_192": ("Wat deed Allah voor de Kinderen van Israël bij de zee, achtervolgd door Farao?", ["Hij spleet de zee en redde hen", "Hij liet de nacht neerdalen", "Hij zond schepen", "Hij droogde de zee voorgoed uit"], "«En toen Wij voor jullie de zee spleten en jullie redden en het volk van Farao lieten verdrinken.»"),
"prophets_193": ("Waarom vroeg Musa Allah om Harun met hem te zenden?", ["Omdat hij welsprekender was dan hij", "Omdat hij ouder was", "Omdat hij Egypte kende", "Omdat hij kon schrijven"], "«En mijn broer Harun is welsprekender dan ik, zend hem dus met mij als steun, die mij bevestigt.»"),
"prophets_194": ("Hoe moesten Musa en Harun tot Farao spreken?", ["Met zachte woorden", "Met dreigementen", "Zonder hem aan te kijken", "Alleen schriftelijk"], "«En spreek tot hem met zachte woorden, opdat hij zich laat vermanen of Allah vreest.»"),
"prophets_195": ("Wie uit Farao's huishouden verdedigde Musa terwijl hij zijn geloof verborg?", ["Een gelovige man uit de familie van Farao", "De hogepriester", "De legeraanvoerder", "De vizier Haman"], "«En een gelovige man uit de familie van Farao, die zijn geloof verborg, zei: “Doden jullie een man omdat hij zegt: mijn Heer is Allah?”»"),
"prophets_196": ("Wat zei Harun tot zijn volk terwijl Musa afwezig was?", ["Dat zij slechts door het kalf beproefd werden, en hem moesten volgen", "Het kalf te behouden", "Naar Egypte te gaan", "Te zwijgen"], "«Mijn volk, jullie worden er slechts door beproefd. En jullie Heer is de Erbarmer, volgt mij dus.»"),
"prophets_197": ("Wat zei de vrouw van Farao toen zij de zuigeling Musa vond?", ["«Hij is een verkoeling van het oog voor mij en voor jou: dood hem niet»", "«Breng hem terug naar zijn moeder»", "«Breng hem naar de rivier»", "«Verkoop hem»"], "«En de vrouw van Farao zei: “Een verkoeling van het oog voor mij en voor jou. Dood hem niet; misschien baat hij ons.”»"),
"prophets_198": ("Hoe vroeg Musa om de kundige dienaar (al-Khidr) te mogen volgen?", ["«Mag ik jou volgen, op voorwaarde dat je mij onderwijst?»", "«Beveel mij en ik gehoorzaam»", "«Onderwijs mij tegen betaling»", "«Kom met mij mee»"], "«Mag ik jou volgen, op voorwaarde dat je mij onderwijst van wat jou aan rechte leiding is onderwezen?»"),
"prophets_199": ("In welke toestand keerde Musa naar zijn volk terug nadat hij het kalf had gezien?", ["Toornig en bedroefd", "Verheugd", "Zwijgend", "Onverschillig"], "«En toen Musa toornig en bedroefd tot zijn volk terugkeerde… wierp hij de tafelen neer.»"),
"prophets_200": ("Welke boodschap moest Musa volgens soera An-Nazi'at aan Farao brengen?", ["«Wil je jezelf reinigen, en zal ik je naar je Heer leiden?»", "«Geef mij mijn volk terug»", "«Bouw mij een paleis»", "«Verlaat Egypte»"], "«Ga naar Farao; hij heeft de perken te buiten gegaan. En zeg: wil je jezelf reinigen, en zal ik je naar je Heer leiden opdat je Hem vreest?»"),
"prophets_201": ("Wie verheerlijkte Allah samen met Dawud, 's avonds en 's ochtends?", ["De bergen en de vogels", "De rivieren", "De sterren", "De winden"], "«Wij maakten de bergen dienstbaar om met hem te verheerlijken bij avond en na zonsopgang, en de vogels, samengebracht.»"),
"prophets_202": ("Wat gaf Allah volgens de Koran aan Dawud, naast een stevig koninkrijk?", ["Wijsheid en een beslissende spraak", "Grote legers", "Goud en zilver", "Een ivoren paleis"], "«En Wij versterkten zijn koninkrijk en gaven hem wijsheid en onderscheidingsvermogen in het spreken.»"),
"prophets_203": ("Wat werd Dawud bevolen aangaande de maliënkolders die hij maakte?", ["De schakels nauwkeurig af te meten", "Zijn naam erop te graveren", "Ze te vergulden", "Ze te verkopen"], "«Maak volledige maliënkolders en meet de schakels nauwkeurig af.»"),
"prophets_204": ("Wat zeiden Dawud en Sulaiman toen Allah hun kennis gaf?", ["«Lof zij Allah, die ons boven vele van Zijn gelovige dienaren heeft begunstigd»", "«Wij zijn de besten»", "«Niemand evenaart ons»", "«Wij hebben het verdiend»"], "«Lof zij Allah, die ons boven vele van Zijn gelovige dienaren heeft begunstigd.»"),
"prophets_205": ("Wat deed Sulaiman toen hij de mier haar volk hoorde waarschuwen?", ["Hij glimlachte en vroeg Allah hem dankbaar te maken", "Hij werd toornig", "Hij liet zijn leger zwijgend omkeren", "Hij gebood stilte"], "«Toen glimlachte hij, geamuseerd om haar woorden, en zei: “Mijn Heer, maak mij dankbaar voor Uw gunst.”»"),
"prophets_206": ("Welk nieuws bracht de hop aan Sulaiman?", ["Een vrouw regeerde over Saba en haar volk knielde voor de zon", "Een leger naderde", "Een droogte had toegeslagen", "Er lag een schat verborgen"], "«Ik ben tot jou gekomen uit Saba met zeker nieuws: ik trof een vrouw aan die over hen heerste… zij knielen voor de zon.»"),
"prophets_207": ("Wat verbaasde de koningin van Saba bij het betreden van Sulaimans paleis?", ["De vloer van glas, die zij voor water hield", "Een tamme leeuw", "Een hangende tuin", "Een gouden troon"], "«Haar werd gezegd: “Treed het paleis binnen.” Toen zij het zag, hield zij het voor een watervlakte en ontblootte haar benen. Hij zei: “Het is een paleis geplaveid met glas.”»"),
"prophets_208": ("Waaruit bestonden Sulaimans legers, volgens de Koran?", ["Djinn, mensen en vogels", "Alleen ruiters", "Zeelieden", "Alleen boogschutters"], "«En voor Sulaiman werden zijn troepen van djinn, mensen en vogels verzameld, en zij werden in rijen opgesteld.»"),
"prophets_209": ("Hoe beschreef Zakariyya zijn toestand toen hij zijn Heer aanriep?", ["«Mijn beenderen zijn verzwakt en mijn hoofd is grijs geworden»", "«Ik ben rijk en verzadigd»", "«Ik ben ver van mijn volk»", "«Ik ben op reis»"], "«Mijn Heer, mijn beenderen zijn verzwakt en mijn hoofd is grijs geworden, en nooit ben ik in mijn smeekbede tot U teleurgesteld.»"),
"prophets_210": ("Welk teken werd Zakariyya gegeven voor de geboorte van Yahya?", ["Drie dagen niet tot de mensen spreken behalve met gebaren", "Een ster", "Regen buiten het seizoen", "Een terugkerende droom"], "«Jouw teken is dat je drie dagen niet tot de mensen zult spreken behalve met gebaren.»"),
"prophets_211": ("Wat werd Yahya gezegd aangaande de Schrift?", ["«Neem de Schrift met kracht»", "«Verberg de Schrift»", "«Kopieer de Schrift»", "«Lees haar eenmaal»"], "«O Yahya, neem de Schrift met vastberadenheid.» En Wij gaven hem het oordeel toen hij nog een kind was."),
"prophets_212": ("Wat bevolen de engelen Maryam nadat zij hadden aangekondigd dat zij uitverkoren was?", ["Haar Heer toegewijd te gehoorzamen, te knielen en te buigen", "Op reis te gaan", "Voorgoed te zwijgen", "In de Tempel te onderwijzen"], "«O Maryam, gehoorzaam je Heer toegewijd, kniel neer en buig met hen die buigen.»"),
"prophets_213": ("Wat moest Maryam schudden om voedsel te krijgen ten tijde van de geboorte?", ["De stam van de palmboom, om verse dadels te laten vallen", "Een olijfboom", "Een vijgenboom", "Een wijnstok"], "«En schud de stam van de palmboom naar je toe; hij zal rijpe, verse dadels op je laten vallen.»"),
"prophets_214": ("Wat zei 'Isa in de wieg dat Allah hem had opgedragen?", ["Het gebed en de zakat, zolang hij leefde", "De handel", "Het zwijgen", "Het reizen"], "«En Hij heeft mij het gebed en de zakat opgedragen zolang ik leef.»"),
"prophets_215": ("Hoe beschrijft soera Az-Zukhruf 'Isa, de zoon van Maryam?", ["Een dienaar aan wie Allah gunst schonk en die Hij tot voorbeeld maakte voor de Kinderen van Israël", "Een koning van Israël", "Een neergezonden engel", "Een schrijver van de Tempel"], "«Hij was niet anders dan een dienaar aan wie Wij gunst schonken, en Wij maakten hem tot een voorbeeld voor de Kinderen van Israël.»"),
"prophets_216": ("Wat zal 'Isa op de Dag der Opstanding antwoorden wanneer Allah hem ondervraagt?", ["«Verheven bent U! Het paste mij niet te zeggen waarop ik geen recht had»", "«Ik herinner het mij niet»", "«Zij hebben het zelf geschreven»", "«Vraag het de discipelen»"], "«Verheven bent U! Het paste mij niet te zeggen waarop ik geen recht heb.»"),
"prophets_217": ("Hoe beschrijft de Koran 'Isa, de zoon van Maryam?", ["De gezant van Allah, Zijn woord dat Hij aan Maryam overbracht, en een geest van Hem", "Een neergezonden engel", "Een rechtvaardige koning", "Een geleerde schrijver"], "«De Messias, 'Isa de zoon van Maryam, was slechts een gezant van Allah en Zijn woord dat Hij aan Maryam overbracht, en een geest van Hem.»"),
"prophets_218": ("Aan welke gunsten herinnert Allah Zijn Profeet ﷺ in soera Ad-Duha?", ["Hij bood hem als wees onderdak, leidde hem en maakte hem onafhankelijk", "Hij gaf hem een koninkrijk", "Hij gaf hem een leger", "Hij gaf hem een paleis"], "«Heeft Hij jou niet als wees gevonden en onderdak geboden? En jou dwalend gevonden en geleid? En jou behoeftig gevonden en onafhankelijk gemaakt?»"),
"prophets_219": ("Welke belofte herhaalt soera Ash-Sharh tweemaal?", ["«Voorwaar, met de moeilijkheid komt de verlichting»", "«De overwinning is nabij»", "«Het Paradijs is beloofd»", "«De vijanden zullen vergaan»"], "«Voorwaar, met de moeilijkheid komt de verlichting. Voorwaar, met de moeilijkheid komt de verlichting.»"),
"prophets_220": ("Wat werd de Profeet ﷺ in soera Al-Kawthar geschonken, en wat werd hem in ruil bevolen?", ["Al-Kawthar; tot zijn Heer te bidden en te offeren", "Een leger; te strijden", "Een koninkrijk; te heersen", "Een schat; die te delen"], "«Voorwaar, Wij hebben jou al-Kawthar geschonken. Bid dus tot je Heer en offer.»"),
"prophets_221": ("Hoe beschrijft soera At-Tawbah de Gezant ﷺ tegenover de gelovigen?", ["Bezorgd om hen, vriendelijk en barmhartig", "Hard en afstandelijk", "Rijk en machtig", "Zwijgzaam en teruggetrokken"], "«Voorzeker, er is tot jullie een Gezant uit jullie eigen midden gekomen… bezorgd om jullie, en voor de gelovigen vriendelijk en barmhartig.»"),
"prophets_222": ("Wat zou de mensen volgens de Koran van de Profeet ﷺ hebben weggedreven, als hij zo was geweest?", ["Als hij ruw en hardvochtig was geweest", "Als hij rijk was geweest", "Als hij jong was geweest", "Als hij zwijgzaam was geweest"], "«Door barmhartigheid van Allah was je zachtmoedig voor hen. Was je ruw en hardvochtig geweest, dan waren zij van je weggelopen.»"),
"prophets_223": ("Wat zegt de Koran over Allah's Gezant ﷺ voor wie op Allah en de Laatste Dag hoopt?", ["Hij is voor hen een uitstekend voorbeeld", "Hij is een koning", "Hij is een rechter", "Hij is een karavaanleider"], "«Voorzeker, in de Gezant van Allah is voor jullie een uitstekend voorbeeld, voor wie hoopt op Allah en de Laatste Dag.»"),
"prophets_224": ("Tot wie werd de profeet Mohammed ﷺ gezonden, volgens soera Saba?", ["Tot de gehele mensheid", "Alleen tot Quraysh", "Alleen tot de Arabieren", "Tot de mensen van Medina"], "«En Wij hebben jou slechts gezonden als brenger van goede tijding en als waarschuwer voor de gehele mensheid.»"),
"prophets_225": ("Welk vers reciteerde de Profeet ﷺ toen de afgoden rond de Ka'ba werden verwijderd?", ["«De waarheid is gekomen en de valsheid is verdwenen»", "«Wij hebben jou een duidelijke overwinning gegeven»", "«Zeg: Hij is Allah, de Ene»", "«Wanneer de hulp van Allah komt»"], "«En zeg: de waarheid is gekomen en de valsheid is verdwenen. Voorwaar, de valsheid moet wel verdwijnen.»"),
"prophets_226": ("Wat zeggen de gelovigen over Allah's gezanten, aan het einde van soera Al-Baqarah?", ["«Wij maken geen onderscheid tussen enigen van Zijn gezanten»", "«Wij volgen alleen de laatste»", "«Wij verkiezen er één van»", "«Wij negeren hen»"], "«Wij maken geen onderscheid tussen enigen van Zijn gezanten. En zij zeiden: wij horen en wij gehoorzamen.»"),
"prophets_227": ("Welke ene boodschap bracht elke gezant aan zijn volk?", ["«Aanbid Allah en vermijd de valse goden»", "«Bouw tempels»", "«Word rijk»", "«Schrijf boeken»"], "«En Wij hebben voorzeker in elke gemeenschap een gezant gezonden, zeggend: aanbid Allah en vermijd de taghut.»"),
"prophets_228": ("In welke taal werd elke gezant gezonden, volgens soera Ibrahim?", ["In de taal van zijn eigen volk, om het hun duidelijk te maken", "Alleen in het Arabisch", "In het Hebreeuws", "In een hemelse taal"], "«En Wij hebben geen gezant gezonden dan in de taal van zijn volk, om het hun duidelijk te maken.»"),
"prophets_229": ("Wat werd volgens soera Al-Anbiya aan elke gezant vóór Mohammed ﷺ geopenbaard?", ["Dat er geen god is dan Hij, aanbid Hem dus", "Een heiligdom te bouwen", "Landen te veroveren", "Het geheim te houden"], "«En Wij hebben vóór jou geen gezant gezonden of Wij openbaarden hem: er is geen god dan Ik, aanbid Mij dus.»"),
"prophets_230": ("Welke groep profeten wordt in soera Al-An'am genoemd als het geleide nageslacht van Ibrahim?", ["Dawud, Sulaiman, Ayyub, Yusuf, Musa en Harun onder anderen", "Alleen Musa en 'Isa", "Alleen Isma'il en Ishaq", "Alleen Nuh en Hud"], "De passage noemt een lange reeks profeten die Allah leidde, zeggend: «En zo belonen Wij hen die goed doen.»"),
"prophets_231": ("Wat zegt de Koran over de gezanten onderling?", ["Allah begunstigde sommigen van hen boven anderen", "Zij zijn allen gelijk in rang", "Alleen de laatste telt", "Zij wisten niets van elkaar"], "«Die gezanten — sommigen van hen hebben Wij boven anderen doen uitmunten.»"),
"prophets_232": ("Welk verbond nam Allah van de profeten, volgens soera Al-'Imran?", ["Te geloven in de Gezant die zou komen ter bevestiging van wat zij hadden, en hem te steunen", "Hun volk nooit te verlaten", "Ieder een tempel te bouwen", "Ieder een boek te schrijven"], "«Als er tot jullie een Gezant komt ter bevestiging van wat jullie hebben, dan moeten jullie in hem geloven en hem steunen.»"),
"prophets_233": ("Welke profeten noemt de Koran wanneer zij zegt dat Allah voor hen dezelfde godsdienst verordende?", ["Nuh, Ibrahim, Musa en 'Isa, samen met wat aan de Profeet ﷺ werd geopenbaard", "Alleen Adam en Idris", "Alleen Dawud en Sulaiman", "Alleen Hud en Salih"], "«Hij heeft voor jullie van de godsdienst verordend wat Hij Nuh opdroeg, en wat Wij aan jou openbaarden, en wat Wij Ibrahim, Musa en 'Isa opdroegen.»"),
"prophets_234": ("Wat zegt de Koran over gezanten wier verhalen zij niet vertelt?", ["Er zijn er wier verhaal Allah de Profeet ﷺ niet heeft verteld", "Zij bestaan niet", "Allen worden genoemd", "Zij doen er niet toe"], "«Onder hen zijn er wier verhaal Wij jou hebben verteld, en onder hen zijn er wier verhaal Wij jou niet hebben verteld.»"),
"prophets_235": ("Uit wie koos Allah al Zijn gezanten, volgens soera Yusuf?", ["Mannen uit de steden, aan wie Hij openbaring zond", "Engelen", "Koningen", "Alleen woestijnbewoners"], "«En Wij hebben vóór jou slechts mannen gezonden aan wie Wij openbaarden, uit de bewoners van de steden.»"),
"prophets_236": ("Wat herinnert de Koran over gezanten die vóór Mohammed ﷺ werden geloochend?", ["Zij waren geduldig tot Onze hulp tot hen kwam", "Zij gaven op", "Zij verborgen zich", "Zij veranderden hun boodschap"], "«Voorzeker, vóór jou werden gezanten geloochend, maar zij waren geduldig onder de loochening tot Onze hulp tot hen kwam.»"),
"prophets_237": ("Welke families verkoos Allah boven de werelden, volgens soera Al-'Imran?", ["Adam, Nuh, de familie van Ibrahim en de familie van 'Imran", "De koningen van Egypte", "De stammen van Medina", "Het volk van Saba"], "«Voorwaar, Allah verkoos Adam en Nuh en de familie van Ibrahim en de familie van 'Imran boven de werelden.»"),
"prophets_238": ("Aan welke gunsten herinnerde Musa zijn volk, toen hij hen uitnodigde het Heilige Land binnen te gaan?", ["Dat Allah profeten onder hen aanstelde en hen koningen maakte", "Dat Hij hun schepen gaf", "Dat Hij hun goud gaf", "Dat Hij hun paarden gaf"], "«Mijn volk, gedenk de gunst van Allah aan jullie toen Hij onder jullie profeten aanstelde en jullie koningen maakte.»"),
"prophets_239": ("Hoe beschreven de Thora en het Evangelie de ongeletterde Profeet, volgens de Koran?", ["Hij gebiedt het goede, verbiedt het slechte en verlicht hun lasten", "Hij brengt rijkdom", "Hij heerst met geweld", "Hij bouwt tempels"], "«…de ongeletterde profeet die zij bij zich beschreven vinden in de Thora en het Evangelie, die hun het goede gebiedt en het slechte verbiedt… en hun lasten verlicht.»"),
"prophets_240": ("Op wie zei Nuh te vertrouwen, terwijl hij zijn volk uitdaagde plannen te beramen?", ["Op Allah, in wie hij zijn vertrouwen stelde", "Op zijn zonen", "Op zijn stam", "Op zijn schip"], "«Op Allah stel ik mijn vertrouwen. Beraam dus jullie plan, jullie en jullie deelgenoten.»"),
"prophets_241": ("Aan wie schrijft Ibrahim in zijn smeekbede de genezing toe wanneer hij ziek is?", ["Aan Allah alleen", "Aan artsen", "Aan kruiden", "Aan de tijd"], "«En wanneer ik ziek ben, is Hij het die mij geneest,» zei Ibrahim toen hij zijn Heer beschreef."),
"prophets_242": ("Waarmee werd Ibrahims zoon vrijgekocht, volgens soera As-Saffat?", ["Met een geweldig offer", "Met een losprijs van goud", "Met een karavaan", "Met een hele kudde"], "«En Wij kochten hem vrij met een geweldig offer.»"),
"prophets_243": ("Waarin verklaren de gelovigen te geloven, in het vers «Zeg: wij geloven in Allah…»?", ["In wat werd geopenbaard aan Ibrahim, Isma'il, Ishaq, Ya'qub, Musa, 'Isa en de profeten", "In slechts één boek", "In slechts één profeet", "In hun eigen tradities"], "«Zeg: wij geloven in Allah en in wat aan ons is neergezonden en in wat werd neergezonden aan Ibrahim, Isma'il, Ishaq, Ya'qub…»"),
"prophets_244": ("Waarom vertelt Allah de verhalen van de gezanten aan de Profeet ﷺ?", ["Om zijn hart te versterken", "Om hem bezig te houden", "Om hem geschiedenis te leren", "Om hem te vermaken"], "«En elk verhaal dat Wij jou vertellen uit het nieuws van de gezanten is datgene waarmee Wij jouw hart versterken.»"),
"prophets_245": ("Wat moest de Profeet ﷺ aan het einde van soera Al-Kahf over zichzelf zeggen?", ["«Ik ben slechts een mens zoals jullie; mij is geopenbaard dat jullie God één God is»", "«Ik ben een koning»", "«Ik ben een engel»", "«Ik ken het onwaarneembare»"], "«Zeg: ik ben slechts een mens zoals jullie, aan wie is geopenbaard dat jullie God één God is.»"),
"prophets_246": ("Hoe beschrijft soera Al-Fath hen die met de Gezant ﷺ zijn?", ["Standvastig tegen de ongelovigen, barmhartig onder elkaar", "Rijk en talrijk", "Zwijgzaam en teruggetrokken", "Reizigers en handelaars"], "«Mohammed is de Gezant van Allah; en zij die met hem zijn, zijn standvastig tegen de ongelovigen, barmhartig onder elkaar.»"),
"prophets_247": ("Wat zegt soera An-Najm over het spreken van de Profeet ﷺ?", ["Hij spreekt niet uit begeerte: het is slechts een geopenbaarde openbaring", "Hij spreekt als een dichter", "Hij spreekt als een waarzegger", "Hij spreekt uit zichzelf"], "«Jullie metgezel is niet afgedwaald, noch heeft hij gedwaald, noch spreekt hij uit begeerte. Het is niets anders dan een geopenbaarde openbaring.»"),
"prophets_248": ("Wat werd de Profeet ﷺ bevolen toen de hulp van Allah en de overwinning kwamen?", ["Zijn Heer te verheerlijken met lof en Zijn vergeving te vragen", "Een feest te houden", "Een monument te bouwen", "Te rusten"], "«Wanneer de hulp van Allah komt en de overwinning… verheerlijk dan je Heer met lof en vraag Hem om vergeving.»"),
"prophets_249": ("Welke drie taken geeft soera Al-Jumu'ah aan de Gezant die tot de ongeletterden werd gezonden?", ["De verzen voordragen, hen zuiveren, en hun het Boek en de wijsheid onderwijzen", "Bouwen, handelen en heersen", "Schrijven, tellen en reizen", "Oordelen, straffen en belasten"], "«Hij is het die onder de ongeletterden een Gezant uit hun midden zond, die hun Zijn verzen voordraagt, hen zuivert, en hun het Boek en de wijsheid onderwijst.»"),
"prophets_250": ("Welke bescherming noemt de Koran zolang de Profeet ﷺ onder hen was?", ["Allah zou hen niet bestraffen zolang hij onder hen was", "Zij zouden rijk zijn", "Zij zouden altijd winnen", "Zij zouden niet sterven"], "«Maar Allah zou hen niet bestraffen terwijl jij onder hen bent.»"),
}
